create function public.check_alert_rate() returns trigger language plpgsql security definer set search_path='' as $$begin if (select count(*) from public.support_alerts where author_id=new.author_id and created_at>now()-interval '1 hour')>=3 then raise exception 'Limite de solicitações por hora atingido'; end if; return new; end$$;
create trigger alert_rate_limit before insert on public.support_alerts for each row execute function public.check_alert_rate();
create function public.alert_created() returns trigger language plpgsql security definer set search_path='' as $$begin insert into public.support_alert_events(alert_id,actor_id,event_type,new_status,metadata) values(new.id,new.author_id,'CREATED',new.status,'{"internal":false}'); insert into public.notifications(recipient_id,type,title,body,href) select id,'ADMIN','Nova solicitação de suporte','Uma nova solicitação aguarda acolhimento.','/admin/alertas' from public.profiles where role in ('STAFF','ADMIN') and suspended_at is null; return new; end$$;
create trigger on_alert_created after insert on public.support_alerts for each row execute function public.alert_created();
create function public.social_notification() returns trigger language plpgsql security definer set search_path='' as $$declare owner uuid; begin select author_id into owner from public.posts where id=new.post_id; if owner<>new.user_id then insert into public.notifications(recipient_id,type,title,body,href) values(owner,'LIKE','Sua publicação recebeu uma curtida','Alguém interagiu com sua publicação.','/inicio'); end if; return new; end$$;
create trigger on_like after insert on public.post_likes for each row execute function public.social_notification();
